'use strict';

// Keep native select values and form submissions, with a consistent accessible popup.
(() => {
  const widgets=new Map();
  let active=null,typed='',typeTimer;
  const create=(tag,className)=>{const el=document.createElement(tag);el.className=className;return el;};
  function close(focus=false){if(!active)return;const item=active;active=null;if(item.popup.matches(':popover-open'))item.popup.hidePopover();item.popup.hidden=true;item.button.setAttribute('aria-expanded','false');item.button.removeAttribute('aria-activedescendant');if(focus)item.button.focus();}
  function sync(item){const option=item.select.selectedOptions[0];const text=option?.label||'请选择';if(item.caption.textContent!==text)item.caption.textContent=text;item.button.disabled=item.select.disabled||!item.select.options.length;item.button.setAttribute('aria-label',item.name+'：'+text);}
  function position(item){const rect=item.button.getBoundingClientRect(),width=Math.max(rect.width,145),height=Math.min(item.popup.scrollHeight,250),room=innerHeight-rect.bottom-12;item.popup.style.width=Math.min(width,innerWidth-24)+'px';item.popup.style.left=Math.max(12,Math.min(rect.left,innerWidth-width-12))+'px';item.popup.style.top=(room>=Math.min(height,140)?rect.bottom+6:Math.max(12,rect.top-height-6))+'px';item.popup.style.maxHeight=Math.min(250,Math.max(120,room>=140?room:rect.top-18))+'px';}
  function highlight(item,index){const options=[...item.popup.children];if(!options.length)return;item.index=(index+options.length)%options.length;options.forEach((el,i)=>el.classList.toggle('highlighted',i===item.index));item.button.setAttribute('aria-activedescendant',options[item.index].id);options[item.index].scrollIntoView({block:'nearest'});}
  function choose(item,index){const option=item.select.options[index];if(!option||option.disabled)return;item.select.value=option.value;sync(item);close(true);item.select.dispatchEvent(new Event('change',{bubbles:true}));}
  function open(item){close();sync(item);item.popup.replaceChildren(...[...item.select.options].map((option,index)=>{const el=create('div','select-option');el.id=item.button.id+'-option-'+index;el.setAttribute('role','option');el.setAttribute('aria-selected',String(option.selected));el.setAttribute('aria-disabled',String(option.disabled));el.textContent=option.label;el.addEventListener('pointerdown',event=>event.preventDefault());el.addEventListener('click',()=>choose(item,index));return el;}));active=item;item.index=Math.max(0,item.select.selectedIndex);item.button.setAttribute('aria-expanded','true');item.popup.hidden=false;item.popup.showPopover();position(item);highlight(item,item.index);}
  function enhance(select){if(widgets.has(select)||select.multiple||select.size>1||!HTMLDivElement.prototype.showPopover)return;const label=select.labels?.[0];const name=select.getAttribute('aria-label')||(label?[...label.childNodes].filter(n=>n.nodeType===Node.TEXT_NODE).map(n=>n.textContent).join('').trim():'选择选项');const wrapper=create('span','custom-select'),button=create('button','select-trigger'),caption=create('span','select-caption'),arrow=create('span','select-arrow'),popup=create('div','select-options');button.type='button';button.id=(select.id||'select-'+widgets.size)+'-control';popup.id=button.id+'-list';button.setAttribute('role','combobox');button.setAttribute('aria-haspopup','listbox');button.setAttribute('aria-expanded','false');button.setAttribute('aria-controls',popup.id);popup.setAttribute('role','listbox');popup.setAttribute('aria-label',name);popup.setAttribute('popover','manual');popup.hidden=true;arrow.setAttribute('aria-hidden','true');button.append(caption,arrow);select.before(wrapper);wrapper.append(button,select);(select.closest('dialog')||document.body).append(popup);select.hidden=true;select.tabIndex=-1;select.setAttribute('aria-hidden','true');if(label?.htmlFor===select.id)label.htmlFor=button.id;const item={select,wrapper,button,caption,popup,name,index:0};widgets.set(select,item);sync(item);button.addEventListener('click',()=>active===item?close():open(item));select.addEventListener('change',()=>sync(item));button.addEventListener('keydown',event=>{if(['ArrowDown','ArrowUp','Home','End','Enter',' '].includes(event.key)){event.preventDefault();if(active!==item){open(item);return;}if(event.key==='Enter'||event.key===' '){choose(item,item.index);return;}highlight(item,event.key==='Home'?0:event.key==='End'?item.select.options.length-1:item.index+(event.key==='ArrowDown'?1:-1));}else if(event.key==='Escape'){event.preventDefault();event.stopPropagation();close(true);}else if(event.key==='Tab')close();else if(event.key.length===1&&!event.ctrlKey&&!event.metaKey){typed+=event.key.toLocaleLowerCase();clearTimeout(typeTimer);typeTimer=setTimeout(()=>typed='',650);if(active!==item)open(item);const index=[...item.select.options].findIndex(option=>option.label.toLocaleLowerCase().startsWith(typed));if(index>=0)highlight(item,index);}});}
  function syncAll(){for(const [select,item]of widgets){if(!select.isConnected){if(active===item)close();item.popup.remove();widgets.delete(select);}else sync(item);}}
  function scan(root){if(root instanceof HTMLSelectElement)enhance(root);root.querySelectorAll?.('select').forEach(enhance);}
  document.addEventListener('pointerdown',event=>{if(active&&!active.wrapper.contains(event.target)&&!active.popup.contains(event.target))close();});
  window.addEventListener('resize',()=>{if(active)position(active);});
  document.addEventListener('scroll',event=>{if(active&&!active.popup.contains(event.target))position(active);},true);
  document.addEventListener('DOMContentLoaded',()=>{scan(document);new MutationObserver(records=>{for(const record of records)for(const added of record.addedNodes)if(added.nodeType===Node.ELEMENT_NODE)scan(added);syncAll();}).observe(document.body,{childList:true,subtree:true});});
  document.addEventListener('close',event=>{if(active&&event.target.contains(active.select))close();},true);
  window.ResourceSelect={sync:syncAll,close};
})();
